group 'com.aivexus.local_image_vision'
version '0.1.0'

buildscript {
    ext.kotlin_version = '2.2.20'
    repositories { google(); mavenCentral() }
    dependencies {
        classpath 'com.android.tools.build:gradle:8.11.1'
        classpath "org.jetbrains.kotlin:kotlin-gradle-plugin:$kotlin_version"
    }
}

apply plugin: 'com.android.library'
apply plugin: 'kotlin-android'

android {
    namespace 'com.aivexus.local_image_vision'
    compileSdk 36
    compileOptions {
        sourceCompatibility JavaVersion.VERSION_17
        targetCompatibility JavaVersion.VERSION_17
    }
    kotlinOptions { jvmTarget = '17' }
    defaultConfig { minSdk 24 }
}
dependencies {
    // Bundled image category labeler: no on-demand model download.
    implementation 'com.google.mlkit:image-labeling:17.0.9'
}

package com.aivexus.local_image_vision

import android.content.Context
import android.app.ActivityManager
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.os.Handler
import android.os.Looper
import com.google.mlkit.vision.common.InputImage
import com.google.mlkit.vision.label.ImageLabeling
import com.google.mlkit.vision.label.defaults.ImageLabelerOptions
import io.flutter.plugin.common.BinaryMessenger
import io.flutter.plugin.common.MethodChannel
import java.io.File
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * Offline image-category recognition. The bundled ML Kit model does not
 * contact an API, understand fine details, or run a multimodal LLM.
 * Never log image paths, labels, bytes, or user questions.
 */
internal object LocalImageVisionBridge {
    private const val channelName = "com.aiorchestrator/local_image_vision"
    private var registeredChannel: MethodChannel? = null
    private const val maxBytes = 8L * 1024 * 1024
    private const val maxDecodedEdge = 1024
    private val busy = AtomicBoolean(false)
    private val worker = Executors.newSingleThreadExecutor()
    private val main = Handler(Looper.getMainLooper())

    fun register(context: Context, messenger: BinaryMessenger) {
        val appContext = context.applicationContext
        MethodChannel(messenger, channelName)
            .also { registeredChannel = it }
            .setMethodCallHandler { call, result ->
                if (call.method != "labelImage") {
                    result.notImplemented()
                    return@setMethodCallHandler
                }
                val path = call.argument<String>("path")
                if (path.isNullOrBlank()) {
                    result.error("INVALID_IMAGE", "Nessuna immagine selezionata.", null)
                    return@setMethodCallHandler
                }
                if (!busy.compareAndSet(false, true)) {
                    result.error("IMAGE_BUSY", "Analisi locale già in corso.", null)
                    return@setMethodCallHandler
                }
                worker.execute {
                    try {
                        val file = File(path)
                        if (!file.isFile || !file.canRead() ||
                            file.length() !in 1L..maxBytes) {
                            main.post {
                                busy.set(false)
                                result.error("INVALID_IMAGE", "Immagine non disponibile o oltre 8 MB.", null)
                            }
                            return@execute
                        }

                        // Refuse a new vision workload if Android is already
                        // under memory pressure. Keep the resident text model
                        // untouched; a single image is never worth an OOM crash.
                        val activityManager = appContext.getSystemService(
                            Context.ACTIVITY_SERVICE
                        ) as? ActivityManager
                        val memory = ActivityManager.MemoryInfo()
                        activityManager?.getMemoryInfo(memory)
                        if (activityManager != null &&
                            (memory.lowMemory || memory.availMem < 256L * 1024 * 1024)) {
                            main.post {
                                busy.set(false)
                                result.error(
                                    "LOCAL_VISION_MEMORY",
                                    "Memoria libera insufficiente per Image LOCAL. " +
                                        "Chiudi altre applicazioni e riprova.",
                                    null
                                )
                            }
                            return@execute
                        }

                        // Decode bounds first, then a downsampled RGB_565 bitmap
                        // to bound peak RAM on devices with small memory budgets.
                        val bounds = BitmapFactory.Options().apply {
                            inJustDecodeBounds = true
                        }
                        BitmapFactory.decodeFile(file.path, bounds)
                        val width = bounds.outWidth
                        val height = bounds.outHeight
                        if (width <= 0 || height <= 0 || width > 16384 || height > 16384) {
                            main.post {
                                busy.set(false)
                                result.error("INVALID_IMAGE", "Formato o dimensioni immagine non supportati.", null)
                            }
                            return@execute
                        }
                        var sampleSize = 1
                        while (width / sampleSize > maxDecodedEdge ||
                            height / sampleSize > maxDecodedEdge) {
                            sampleSize *= 2
                        }
                        val options = BitmapFactory.Options().apply {
                            inSampleSize = sampleSize
                            inPreferredConfig = Bitmap.Config.RGB_565
                        }
                        val bitmap = BitmapFactory.decodeFile(file.path, options)
                            ?: throw IllegalArgumentException("cannot decode image")
                        main.post {
                            val labeler = ImageLabeling.getClient(
                                ImageLabelerOptions.Builder()
                                    .setConfidenceThreshold(0.55f)
                                    .build()
                            )
                            try {
                                labeler.process(InputImage.fromBitmap(bitmap, 0))
                                    .addOnSuccessListener { labels ->
                                        val payload = labels
                                            .sortedByDescending { it.confidence }
                                            .take(5)
                                            .map {
                                                mapOf(
                                                    "label" to it.text,
                                                    "confidence" to it.confidence.toDouble()
                                                )
                                            }
                                        result.success(payload)
                                    }
                                    .addOnFailureListener {
                                        result.error(
                                            "LOCAL_VISION_FAILED",
                                            "Riconoscimento visivo locale non riuscito.",
                                            null
                                        )
                                    }
                                    .addOnCompleteListener {
                                        bitmap.recycle()
                                        labeler.close()
                                        busy.set(false)
                                    }
                            } catch (_: Exception) {
                                bitmap.recycle()
                                labeler.close()
                                busy.set(false)
                                result.error(
                                    "LOCAL_VISION_FAILED",
                                    "Riconoscimento visivo locale non riuscito.",
                                    null
                                )
                            }
                        }
                    } catch (_: OutOfMemoryError) {
                        main.post {
                            busy.set(false)
                            result.error("LOCAL_VISION_OOM", "Memoria insufficiente per analizzare la foto.", null)
                        }
                    } catch (_: Exception) {
                        main.post {
                            busy.set(false)
                            result.error("LOCAL_VISION_FAILED", "Impossibile leggere la foto sul dispositivo.", null)
                        }
                    }
                }
            }
    }

    fun unregister() {
        registeredChannel?.setMethodCallHandler(null)
        registeredChannel = null
    }
}

package com.aivexus.local_image_vision

import io.flutter.embedding.engine.plugins.FlutterPlugin

/** Automatically registered by Flutter; the host must NOT also register the
 * original Cantiere MainActivity channel or duplicate listeners will compete. */
class LocalImageVisionPlugin : FlutterPlugin {
    override fun onAttachedToEngine(binding: FlutterPlugin.FlutterPluginBinding) {
        LocalImageVisionBridge.register(binding.applicationContext, binding.binaryMessenger)
    }

    override fun onDetachedFromEngine(binding: FlutterPlugin.FlutterPluginBinding) {
        LocalImageVisionBridge.unregister()
    }
}

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

import 'src/local_image_labels.dart';

export 'src/local_image_labels.dart';

/// Android ML Kit offline image category classification, not a multimodal LLM.
///
/// The native plugin limits file size to 8 MiB, checks memory and downscales
/// bitmaps. This wrapper never sends the picture, prompt or context to Cloud.
class CantiereLocalImageVision {
  CantiereLocalImageVision({
    MethodChannel? channel,
    bool? supportedPlatform,
  })  : _channel = channel ??
            const MethodChannel('com.aiorchestrator/local_image_vision'),
        _supportedPlatform = supportedPlatform ??
            (!kIsWeb && defaultTargetPlatform == TargetPlatform.android);

  static const Duration timeout = Duration(seconds: 20);
  final MethodChannel _channel;
  final bool _supportedPlatform;

  Future<LocalImageLabelResult> labelFile(String imagePath) async {
    if (!_supportedPlatform) {
      throw UnsupportedError(
        'Image LOCAL ML Kit richiede Android. Nessuna immagine inviata al Cloud.',
      );
    }
    if (imagePath.trim().isEmpty) {
      throw ArgumentError.value(imagePath, 'imagePath', 'Missing local image');
    }
    final response = await _channel.invokeMethod<List<dynamic>>(
      'labelImage',
      <String, String>{'path': imagePath},
    ).timeout(timeout);
    return LocalImageLabelProcessor.fromNative(response ?? <Object?>[]);
  }
}

/// Pure Dart post-processing of offline Android image labels.
///
/// Extracted/adapted from the pinned Cantiere vision service. Image decoding,
/// ML Kit model inference, file limits and RAM checks remain the Android
/// host bridge's responsibility. No IO, telemetry, network or Cloud routing.
class LocalImageLabel {
  const LocalImageLabel(this.name, this.confidence);
  final String name;
  final double confidence;
}

class LocalImageLabelResult {
  const LocalImageLabelResult({required this.labels, required this.text});
  static const String providerId = 'localImageLabels';
  final List<LocalImageLabel> labels;
  final String text;
  bool get hasCategories => labels.isNotEmpty;
}

abstract final class LocalImageLabelProcessor {
  static const double minConfidence = 0.55;
  static const int maxLabels = 5;

  static LocalImageLabelResult fromNative(Iterable<Object?> rawLabels) {
    final labels = <LocalImageLabel>[];
    for (final item in rawLabels) {
      if (item is! Map) continue;
      final rawName = item['label'];
      final rawConfidence = item['confidence'];
      if (rawName is! String || rawConfidence is! num) continue;
      final name = rawName.trim().replaceAll(RegExp(r'\s+'), ' ');
      final confidence = rawConfidence.toDouble();
      if (name.isEmpty ||
          name.length > 70 ||
          !confidence.isFinite ||
          confidence < minConfidence ||
          confidence > 1) {
        continue;
      }
      labels.add(LocalImageLabel(name, confidence));
    }
    labels.sort((a, b) => b.confidence.compareTo(a.confidence));
    final selected = List<LocalImageLabel>.unmodifiable(labels.take(maxLabels));

    if (selected.isEmpty) {
      return const LocalImageLabelResult(
        labels: <LocalImageLabel>[],
        text: 'Non ho riconosciuto categorie visive con sufficiente '
            'affidabilità in questa foto. Il riconoscitore offline attuale '
            'è limitato; non posso descrivere dettagli, colori o testo '
            'dell\'immagine. Nessun dato è stato inviato al Cloud.',
      );
    }
    final detected = selected.map(
      (label) => '${label.name} (${(label.confidence * 100).round()}%)',
    );
    return LocalImageLabelResult(
      labels: selected,
      text: 'Riconoscimento visivo sul dispositivo (categorie probabili): '
          '${detected.join(', ')}.\n'
          'Queste sono etichette stimate da un classificatore offline, '
          'non una descrizione completa. Non posso ancora dedurre con '
          'affidabilità colori, quantità, testo o altri dettagli della foto. '
          'Nessuna immagine è stata inviata al Cloud.',
    );
  }
}

import 'package:cantiere_local_image_vision/cantiere_local_image_vision.dart';
import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();
  const channel = MethodChannel('com.aiorchestrator/local_image_vision');
  final messenger =
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger;

  tearDown(() => messenger.setMockMethodCallHandler(channel, null));

  test('invokes only local filepath and filters labels without Cloud', () async {
    var calls = 0;
    messenger.setMockMethodCallHandler(channel, (call) async {
      calls++;
      expect(call.method, 'labelImage');
      expect(call.arguments, <String, String>{'path': '/tmp/fruit.png'});
      return <Map<String, Object>>[
        {'label': 'Apple', 'confidence': 0.94},
        {'label': 'Unknown', 'confidence': 0.14}
      ];
    });
    final result = await CantiereLocalImageVision(
      supportedPlatform: true,
    ).labelFile('/tmp/fruit.png');
    expect(calls, 1);
    expect(result.labels, hasLength(1));
    expect(result.text, contains('Apple (94%)'));
    expect(result.text, isNot(contains('Unknown')));
    expect(result.text, contains('non una descrizione completa'));
  });

  test('no labels reports uncertainty, no invented details', () async {
    messenger.setMockMethodCallHandler(channel, (call) async => <Object>[]);
    final result = await CantiereLocalImageVision(
      supportedPlatform: true,
    ).labelFile('/tmp/unknown.png');
    expect(result.hasCategories, isFalse);
    expect(result.text, contains('Non ho riconosciuto categorie'));
  });

  test('unsupported target rejects before invoking native bridge', () async {
    var calls = 0;
    messenger.setMockMethodCallHandler(channel, (call) async {
      calls++;
      return <Object>[];
    });
    await expectLater(
      CantiereLocalImageVision(
        supportedPlatform: false,
      ).labelFile('/tmp/fruit.png'),
      throwsUnsupportedError,
    );
    expect(calls, 0);
  });

  test('empty filepath rejects before invoking native bridge', () async {
    var calls = 0;
    messenger.setMockMethodCallHandler(channel, (call) async {
      calls++;
      return <Object>[];
    });
    await expectLater(
      CantiereLocalImageVision(
        supportedPlatform: true,
      ).labelFile('  '),
      throwsArgumentError,
    );
    expect(calls, 0);
  });

  test('ML Kit errors are propagated, not replaced with fabricated labels',
      () async {
    messenger.setMockMethodCallHandler(channel, (call) async {
      throw PlatformException(code: 'LOCAL_VISION_MEMORY');
    });
    await expectLater(
      CantiereLocalImageVision(
        supportedPlatform: true,
      ).labelFile('/tmp/fruit.png'),
      throwsA(isA<PlatformException>().having(
        (e) => e.code, 'code', 'LOCAL_VISION_MEMORY',
      )),
    );
  });
}
